mod pencil;mod linear;mod small;mod public;mod finish;
#[path="../native-deferred-membership/validate.rs"]mod validate;
#[path="../native-pencil-images/images.rs"]mod images;
#[path="../native-prepared-solvers/prepared.rs"]mod prepared;
#[path="../native-prepared-solvers/table_oracle.rs"]mod table_oracle;
#[path="../native-prepared-solvers/tail.rs"]mod tail;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng};
fn key<'a>(l:&'a str,k:&str)->Option<&'a str>{l.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn nonaudit(s:&str)->String{let(a,b)=s.split_once("dense_audits: ").unwrap();let(_,b)=b.split_once(',').unwrap();format!("{a}dense_audits: 0,{b}")}
fn main(){let old=include_str!("../native-affine-forest/CONTROL.txt");let mut calls=0;for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c.to_string(),v[2]);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let c=&inst.curve;let mut rng=Rng::new(2026111800^p^((g as u64)<<32));for case in 0..2{let sm=if case==0{1}else{17};let d=c.mul(&inst.d1,sm);let expected=1+rng.below(ell-1);let t=c.mul(&d,expected);let mut signatures=vec![];for arm in 0..3{counted::disable();assert!(validate::eligible(c,&d,&t,ell));let prep=prepared::prepare(c,true);let options=pencil::Options{normalize:arm>0,finish:arm==2,seed:2026112200^p^((g as u64)<<32)^case as u64};let r=pencil::solve(c,&d,&t,ell,512,true,&prep,options);assert_eq!(r.k,Some(expected));assert_eq!(c.mul(&d,expected),t);signatures.push(nonaudit(&format!("{r:?}")));}
let mut prior=std::collections::BTreeMap::new();for rep in 0..2{let arms=if(case+rep)%2==0{[0,1,2]}else{[2,1,0]};for arm in arms{let name=["forest","normalized","lazy_finish"][arm];eprintln!("start g={g} p={p} sm={sm} arm={name} rep={rep}");counted::reset();assert!(validate::eligible(c,&d,&t,ell));let prep=prepared::prepare(c,false);let options=pencil::Options{normalize:arm>0,finish:arm==2,seed:2026112200^p^((g as u64)<<32)^case as u64};let r=pencil::solve(c,&d,&t,ell,512,false,&prep,options);let counts=counted::snapshot();counted::disable();assert_eq!(r.k,Some(expected));assert_eq!(c.mul(&d,expected),t);let signature=format!("{r:?}");assert_eq!(signature,signatures[arm]);let lookup=(prep.roots.sqrt_lookups.get(),prep.roots.legendre_lookups.get(),prep.roots.bytes());let state=(signature.clone(),counts.clone(),lookup);if let Some(previous)=prior.get(&arm){assert_eq!(previous,&state);}else{prior.insert(arm,state);}for(modulus,values)in counts{assert_eq!(values[8],2*values[7]+values[5]+values[6]);if arm==0{let line=old.lines().find(|l|l.starts_with("COUNT ")&&key(l,"g")==Some(v[0])&&key(l,"p")==Some(v[1])&&key(l,"source_multiple")==Some(sm.to_string().as_str())&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"rep")==Some("0")&&key(l,"modulus")==Some(modulus.to_string().as_str())).unwrap();let vv:Vec<u64>=line.split("vector=[").nth(1).unwrap().trim_end_matches(']').split(',').map(|s|s.trim().parse().unwrap()).collect();assert_eq!(values.as_slice(),vv.as_slice());}println!("COUNT g={g} p={p} sm={sm} case={case} arm={name} rep={rep} modulus={modulus} vector={values:?}");}println!("OUTCOME g={g} p={p} sm={sm} case={case} arm={name} rep={rep} sqrt_lookups={} legendre_lookups={} root_bytes={} report={signature}",lookup.0,lookup.1,lookup.2);calls+=1;}}counted::disable();let prep=prepared::prepare(c,true);let outside=prep.fb.iter().map(|&(x,y)|c.place(x,y)).find(|q|!c.is_zero(&c.mul(q,ell)));if let Some(q)=outside{let bad=c.add(&t,&q);assert!(!c.is_zero(&c.mul(&bad,ell)));for arm in 1..3{assert!(validate::eligible(c,&d,&bad,ell));let opts=pencil::Options{normalize:true,finish:arm==2,seed:2026112200^p^((g as u64)<<32)^case as u64};let r=pencil::solve(c,&d,&bad,ell,512,true,&prep,opts);assert_eq!(r.k,None);println!("NEGATIVE g={g} p={p} sm={sm} case={case} arm={arm} report={r:?}");}}else{println!("NEGATIVE_UNAVAILABLE g={g} p={p} sm={sm} case={case}");}}}assert_eq!(calls,132);eprintln!("PASS counted_calls=132 audit_calls=66 native_answers=true audit_report_replay=true repeated_full_vectors_and_lookups_exact=true old_forest_full16_replay=true all_setup_and_search_charged=true no_wall_or_tenfold_claim=true");}
